const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n \"pr-refetch-fix|DIFF-1|diffpanel|skillplane\" /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":3500}),
  Promise.resolve(ALL_TOOLS.filter(x => /skillplane/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,180)})))
]); r.forEach((v,i)=>text(JSON.stringify({i,...v})));

const r=await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '395,421p' /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":2000}),
  tools.exec_command({cmd:"command -v skillplane; command -v splane; command -v composio; command -v rex; command -v orca","max_output_tokens":300}),
  tools.exec_command({cmd:"cat /Users/serro/.agents/skills/composio-cli/SKILL.md","max_output_tokens":3500})
]);r.forEach((v,i)=>text(JSON.stringify({i,...v})));

